const rows = $input.all().map(i => i.json);
const day = r => String(r.date).slice(0, 10);
const today = new Date().toISOString().slice(0, 10);
const days = [...new Set(rows.map(day))].filter(d => d < today).sort();
const reportDay = days[days.length - 1];
const prevDay = days[days.length - 2];

function stats(d) {
  const list = rows.filter(r => day(r) === d);
  const paid = list.filter(r => r.status === 'paid');
  const sum = a => a.reduce((s, r) => s + Number(r.total_etb || 0), 0);
  const byProduct = {};
  for (const r of paid) byProduct[r.product] = (byProduct[r.product] || 0) + Number(r.total_etb || 0);
  const top = Object.entries(byProduct).sort((a, b) => b[1] - a[1]).slice(0, 3)
    .map(([p, v]) => `${p} (${v} ETB)`);
  return {
    orders: list.length,
    paid_orders: paid.length,
    revenue_etb: sum(paid),
    avg_order_etb: paid.length ? Math.round(sum(paid) / paid.length) : 0,
    pending_orders: list.filter(r => r.status === 'pending').length,
    pending_value_etb: sum(list.filter(r => r.status === 'pending')),
    cancelled: list.filter(r => r.status === 'cancelled').length,
    top_products: top,
  };
}
const cur = stats(reportDay), prev = stats(prevDay);
const change = prev.revenue_etb ? Math.round((cur.revenue_etb - prev.revenue_etb) / prev.revenue_etb * 100) : null;
return [{ json: { report_day: reportDay, previous_day: prevDay, ...cur, revenue_change_pct: change, previous_revenue_etb: prev.revenue_etb } }];
